function hydrateMember(data,program){const today=new Date().toISOString().slice(0,10),current=data.subscriptions.find(s=>s.status==='active'&&s.starts_on<=today&&s.ends_on>=today),pending=data.subscriptions.find(s=>s.status==='awaiting_payment'),initialPending=Boolean(pending&&data.subscriptions.length===1),scheduled=data.subscriptions.find(s=>s.status==='active'&&s.starts_on>today),sub=current||pending||scheduled||data.subscriptions[0],plan=sub&&(sub.plan||data.plans.find(p=>String(p.id)===String(sub.plan_id))),hero=document.getElementById('memberSubscription');if(hero){const remaining=current?.ends_on?Math.max(0,Math.ceil((new Date(current.ends_on)-new Date())/864e5)+1):0,percent=current?.starts_on&&current?.ends_on?Math.max(0,Math.min(100,Math.round((Date.now()-new Date(current.starts_on))/(new Date(current.ends_on)-new Date(current.starts_on))*100))):0,renew=document.getElementById('renewSubscription');hero.querySelector('.badge').className=`badge ${sub?.status||'expired'}`;hero.querySelector('.badge').textContent=pending?(initialPending?'بانتظار الدفع الأول':'بانتظار دفع التجديد'):scheduled?'تجديد مجدول':current?'فعال':statusLabel[sub?.status]||'منتهي';hero.querySelector('h2').textContent=pending?(initialPending?'اشتراكك بانتظار التفعيل':'طلب التجديد مسجّل'):scheduled?`سيبدأ ${date(scheduled.starts_on)}`:current?`باقي ${remaining} يوم`:'انتهى الاشتراك';hero.querySelector('p').textContent=plan?`${plan.name_ar} · ${pending?(initialPending?'راجع الإدارة لتأكيد أول دفعة':'راجع الإدارة لتأكيد دفع التجديد'):scheduled?`مجدول من ${date(scheduled.starts_on)} حتى ${date(scheduled.ends_on)}`:current?`فعال حتى ${date(current.ends_on)}`:'اطلب التجديد للمتابعة'}`:'تواصل مع الإدارة لاستكمال الاشتراك.';hero.querySelector('.membership-ring strong').textContent=current?`${percent}%`:'—';if(renew)renew.hidden=Boolean(pending||scheduled||(current&&remaining>7))}const latest=data.measurements.find(m=>m.member_id===currentProfile.id),box=document.getElementById('memberMeasurements');if(latest)box.innerHTML=`<div class="measurement-summary"><div><b>${latest.weight_kg}</b><small>كغ وزن</small></div><div><b>${latest.height_cm}</b><small>سم طول</small></div><div><b>${latest.waist_cm||'—'}</b><small>سم خصر</small></div><div><b>${date(latest.recorded_at)}</b><small>آخر تحديث</small></div></div>`;if(program){const area=document.getElementById('memberProgramArea');area.innerHTML='<article class="card program-preview" id="memberProgram"></article>';showProgram(program,document.getElementById('memberProgram'))}}
async function prepareWomenGroup(data){const buttons=[document.getElementById('womenGroupButton'),document.getElementById('womenGroupTopButton')].filter(Boolean),today=new Date().toISOString().slice(0,10),eligible=currentProfile?.gender==='female'&&data.subscriptions.some(s=>s.status==='active'&&s.starts_on<=today&&s.ends_on>=today);if(!eligible){buttons.forEach(button=>button.remove());return}let link=null;try{link=await StrongGymAPI.memberGroupLink()}catch{}buttons.forEach(button=>{button.hidden=false;button.onclick=()=>link?window.open(link,'_blank','noopener'):notify('تواصلي مع الإدارة للحصول على رابط المجموعة الجديد','error')})}
function hydrateHealth(health){memberHealth=health;const account=document.getElementById('accountForm');if(account&&currentProfile){account.elements.full_name.value=currentProfile.full_name||'';account.elements.whatsapp_e164.value=currentProfile.whatsapp_e164||''}const form=document.getElementById('healthForm');if(!form||!health)return;form.elements.birth_date.value=health.birth_date||'';form.elements.activity_level.value=health.activity_level||'moderate';form.elements.goal.value=health.goal||'fitness';form.elements.medical_notes.value=health.medical_notes||'';['injuries','medical_conditions','food_allergies','dietary_preferences'].forEach(name=>form.querySelectorAll(`[name="${name}"]`).forEach(input=>input.checked=(health[name]||[]).includes(input.value)));const state=document.getElementById('medicalReviewState');if(state){state.hidden=!health.requires_review;state.classList.toggle('cleared',Boolean(health.medical_clearance));state.textContent=health.requires_review?(health.medical_clearance?'تمت مراجعة الحالة والسماح بإنشاء البرنامج.':'الحالة تحتاج مراجعة الإدارة/مختص قبل إنشاء البرنامج.') :''}if(health.birth_date){const born=new Date(`${health.birth_date}T00:00:00`),today=new Date();let age=today.getFullYear()-born.getFullYear();if(today<new Date(today.getFullYear(),born.getMonth(),born.getDate()))age--;const ageInput=document.getElementById('a');if(ageInput&&age>0)ageInput.value=age}}
async function connectAccount(){if(!window.StrongGymAPI)throw new Error('تعذر تحميل الاتصال الآمن');currentProfile=await StrongGymAPI.profile();if(!currentProfile||currentProfile.status!=='active'){location.replace('index.html?login=1');return}const adminPage=location.pathname.toLowerCase().includes('admin');if(adminPage&&!['manager','coach'].includes(currentProfile.role)){location.replace('member.html');return}document.querySelectorAll('.person b').forEach(el=>el.textContent=currentProfile.full_name);await loadNotifications();if(adminPage){await refreshAdmin();goView(location.hash.slice(1)||'overview',false)}else{document.querySelector('.top h1').textContent=`أهلاً ${currentProfile.full_name} 👋`;const data=await StrongGymAPI.memberDashboardData(),program=data.program,health=data.health;currentMemberProgram=program;memberMealLogs=data.meals;memberWorkoutLogs=program?await StrongGymAPI.workoutLogs(program.id):[];hydrateMember(data,program);await prepareWomenGroup(data);hydrateHealth(health);renderNutrition()}}
document.getElementById('renewSubscription')?.addEventListener('click',async event=>{const button=event.currentTarget;button.disabled=true;try{await StrongGymAPI.requestRenewal();notify('تم إرسال طلب التجديد. راجع الإدارة لتأكيد الدفع');button.hidden=true;setTimeout(()=>location.reload(),900)}catch(error){const messages={renewal_already_requested:'طلب التجديد مسجّل مسبقًا',renewal_already_scheduled:'يوجد تجديد مجدول بالفعل'};notify(messages[error.message]||error.message,'error');button.disabled=false}});
async function logout(){document.querySelectorAll('#logoutBtn,.top-logout').forEach(button=>button.disabled=true);try{await StrongGymAPI.signOut()}finally{location.replace('index.html')}}document.querySelectorAll('#logoutBtn,.top-logout').forEach(button=>button.addEventListener('click',logout));
function tokenIssuedAt(token){try{const payload=JSON.parse(atob(token.split('.')[1].replace(/-/g,'+').replace(/_/g,'/')));return Number(payload.iat||0)*1000}catch{return 0}}
async function checkForcedLogout(){if(!currentProfile||currentProfile.role!=='member'||document.hidden)return;try{const [fresh,current]=await Promise.all([StrongGymAPI.profile(),StrongGymAPI.session()]),kickedAt=Date.parse(fresh?.force_logout_at||'');if(kickedAt&&kickedAt>tokenIssuedAt(current?.access_token||'')){StrongGymAPI.clearLocalSession();location.replace('index.html?login=1&kicked=1')}}catch{}}
setInterval(checkForcedLogout,30000);window.addEventListener('focus',checkForcedLogout);document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkForcedLogout()});
document.getElementById('mealEntry')?.addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=event.submitter,data=new FormData(form),body={logged_on:new Date().toISOString().slice(0,10),meal_name:data.get('meal_name').trim(),calories:Number(data.get('calories')),protein_g:Number(data.get('protein_g')||0),water_ml:Number(data.get('water_ml')||0)};button.disabled=true;try{const saved=await StrongGymAPI.addMealLog(body),row=Array.isArray(saved)?saved[0]:saved;if(row)memberMealLogs.unshift(row);form.reset();form.elements.protein_g.value=0;form.elements.water_ml.value=0;renderNutrition();notify('تمت إضافة الوجبة وتحديث المتبقي')}catch(error){notify(error.message,'error')}finally{button.disabled=false}});
connectAccount().catch(error=>{notify(error.message,'error');setTimeout(()=>location.replace('index.html?login=1'),1800)});
const assistantForm=document.querySelector('.assistant-form');if(assistantForm)assistantForm.innerHTML='<label><span>الوزن <small>كيلوغرام</small></span><div class="metric-input"><input id="w" type="number" value="70" min="25" max="300" aria-label="الوزن بالكيلوغرام"><b>kg</b></div></label><label><span>الطول <small>سنتيمتر</small></span><div class="metric-input"><input id="h" type="number" value="165" min="100" max="230" aria-label="الطول بالسنتيمتر"><b>cm</b></div></label><label><span>العمر <small>سنة</small></span><div class="metric-input"><input id="a" type="number" value="25" min="12" max="100" aria-label="العمر بالسنوات"><b>yr</b></div></label>';
const assistantCard=document.getElementById('assistant');if(assistantCard){const account=document.createElement('article');account.className='card health-card full';account.id='accountSettings';account.innerHTML='<div class="card-head"><div><h2>إعدادات الحساب</h2><small class="card-sub">تعديل الاسم ورقم WhatsApp أو تغيير كلمة المرور.</small></div></div><form class="health-form" id="accountForm"><label>الاسم الكامل<input name="full_name" required></label><label>رقم WhatsApp<input name="whatsapp_e164" dir="ltr" placeholder="+972 59 000 0000"></label><button class="db-btn primary" type="submit">حفظ البيانات</button></form><form class="health-form password-form" id="passwordForm"><label>كلمة المرور الجديدة<input name="password" type="password" minlength="8" required autocomplete="new-password"></label><label>تأكيد كلمة المرور<input name="confirm_password" type="password" minlength="8" required autocomplete="new-password"></label><button class="db-btn" type="submit">تغيير كلمة المرور</button></form>';assistantCard.before(account)}
document.getElementById('accountForm')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=e.submitter;button.disabled=true;try{await StrongGymAPI.updateOwnProfile(form.elements.full_name.value.trim(),form.elements.whatsapp_e164.value.trim());currentProfile.full_name=form.elements.full_name.value.trim();document.querySelectorAll('.person b').forEach(el=>el.textContent=currentProfile.full_name);notify('تم تحديث بيانات الحساب')}catch(error){notify(error.message,'error')}finally{button.disabled=false}});
document.getElementById('passwordForm')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;if(form.elements.password.value!==form.elements.confirm_password.value)return notify('كلمتا المرور غير متطابقتين','error');const button=e.submitter;button.disabled=true;try{await StrongGymAPI.updatePassword(form.elements.password.value);form.reset();notify('تم تغيير كلمة المرور بنجاح')}catch(error){notify(error.message,'error')}finally{button.disabled=false}});
document.getElementById('healthForm')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=e.submitter,data=new FormData(form),values={birth_date:form.elements.birth_date.value,activity_level:form.elements.activity_level.value,goal:form.elements.goal.value,medical_notes:form.elements.medical_notes.value.trim()||null,injuries:data.getAll('injuries'),medical_conditions:data.getAll('medical_conditions'),food_allergies:data.getAll('food_allergies'),dietary_preferences:data.getAll('dietary_preferences')};button.disabled=true;try{const saved=await StrongGymAPI.saveHealthProfile(values),row=Array.isArray(saved)?saved[0]:saved;memberHealth=row||values;hydrateHealth(memberHealth);notify(memberHealth.requires_review&&!memberHealth.medical_clearance?'تم الحفظ. يجب مراجعة الحالة قبل إنشاء البرنامج':'تم حفظ ملفك الصحي بأمان')}catch(error){notify(error.message,'error')}finally{button.disabled=false}});
const calc=document.getElementById('strongCalc');if(calc)calc.onclick=()=>{const w=+document.getElementById('w').value||70,h=+document.getElementById('h').value||165,a=+document.getElementById('a').value||25,activity={low:1.25,moderate:1.45,high:1.65}[memberHealth?.activity_level]||1.4,goal=memberHealth?.goal||'fitness',goalAdjust={weight_loss:-350,muscle_gain:250,fitness:0,maintenance:0}[goal]||0,bmr=10*w+6.25*h-5*a+(currentProfile?.gender==='male'?5:-161),c=Math.max(currentProfile?.gender==='male'?1500:1200,Math.round((bmr*activity+goalAdjust)/50)*50),protein=Math.round(w*(goal==='muscle_gain'?2:goal==='weight_loss'?1.8:1.6)),fat=Math.round(w*.8),carbs=Math.max(80,Math.round((c-protein*4-fat*9)/4)),water=Number((w*(memberHealth?.activity_level==='high'?.04:.035)).toFixed(1)),glasses=Math.ceil(water/.25),bmi=(w/((h/100)**2)).toFixed(1),bmiLabel=bmi<18.5?'أقل من الطبيعي':bmi<25?'ضمن الطبيعي':bmi<30?'أعلى من الطبيعي':'مرتفع',goalName={weight_loss:'نزول الوزن',muscle_gain:'زيادة الكتلة العضلية',fitness:'اللياقة العامة',maintenance:'المحافظة على الوزن'}[goal]||'هدف عام',meals=[['الإفطار',25],['الغداء',35],['وجبة خفيفة',15],['العشاء',25]];document.getElementById('calcResult').innerHTML=`<div class="calc-heading"><div><span>خطتك لهدف</span><b>${goalName}</b></div><div class="bmi-chip">BMI ${bmi}<small>${bmiLabel}</small></div></div><div class="calc-metrics"><div class="calories"><span>🔥</span><b>${c}</b><small>سعرة يوميًا</small></div><div><span>🥩</span><b>${protein}غ</b><small>بروتين</small></div><div><span>🍚</span><b>${carbs}غ</b><small>كربوهيدرات</small></div><div><span>🥑</span><b>${fat}غ</b><small>دهون</small></div></div><div class="water-plan"><div class="water-orb"><b>${water}</b><small>لتر</small></div><div><b>هدف الماء اليومي</b><span>${glasses} أكواب تقريبًا · وزّعها من الصباح حتى المساء</span><div class="water-drops">${Array.from({length:Math.min(glasses,12)},(_,i)=>`<i style="--delay:${i}"></i>`).join('')}</div></div></div><div class="meal-split"><b>توزيع السعرات المقترح</b>${meals.map(([name,p])=>`<div><span>${name}</span><div><i style="width:${p}%"></i></div><strong>${Math.round(c*p/100)}</strong></div>`).join('')}</div><p class="calc-note">حساب إرشادي يتغير حسب النشاط والحالة الصحية. حدّث ملفك الصحي لتحصل على نتيجة أدق.</p>`};
